/**
 * Injected script to access the window's `tinyMCE` instance.
 *
 * Appends payload's `html` into the editor named `editor`. Falls back
 * to using the active editor if `editor` is not found, and will also
 * fall back to using `plain` instead of `html` if `html` is not in the payload`.
 *
 * See: https://stackoverflow.com/questions/9515704 (Method #1)
 * Linked from: https://stackoverflow.com/questions/59804297
 *
 * Tiny MCE docs:
 * https://www.tiny.cloud/docs/tinymce/latest/editor-command-identifiers/#core-editor-commands
 */

(() => {
  try {
    const {
      html,
      plain,
      editor: editorName,
    } = JSON.parse(document.currentScript?.dataset.params ?? "{}");

    const tiny = (window as any).tinyMCE;
    const editor = tiny.get(editorName) ?? tiny.activeEditor;
    if (!editor) return;

    // Move cursor to end to append new data
    editor.selection.select(editor.getBody(), true);
    editor.selection.collapse(false);
    editor.focus();

    if (html) {
      editor.execCommand("InsertHTML", false, html);
    } else if (plain) {
      editor.execCommand("InsertText", false, plain);
    }
  } catch {}
})();
